# భూగోళశాస్త్రం (gs1–gs6) – Mission March SSC-2027 ప్రశ్నల బ్యాంక్ (Social_Final.pdf ముద్రిత పేజీలు 5–12)
import os, sys, math
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
from figlib import F, SECTOR, T

def pie(data, cap):
    """data = [(పేరు, విలువ, రంగు)] – వృత్త రేఖాచిత్రం"""
    tot = sum(v for _, v, _ in data); a = 90.0; e = []
    for nm, v, col in data:
        d = 360.0 * v / tot; e.append(SECTOR(0, 0, 2, a, a + d, col, '#1f2937'))
        m = math.radians(a + d / 2); e.append(T(1.15 * math.cos(m), 1.15 * math.sin(m) - 0.08, f'{nm} {v}%', 'middle', 11, None, 1))
        e.append(T(2.55 * math.cos(m), 2.55 * math.sin(m) - 0.08, f'{d:.1f}°', 'middle', 10)); a += d
    return F([-3.1, 3.1, -2.8, 2.8], *e, w=260, cap=cap, al=cap)

